/* Browser-local sample gallery. Real authorization remains in PHP. */
galleryPage=function(){const aid=Number(location.hash.split('/')[2]||0),albums=state.albums.filter(a=>a.visible).sort((a,b)=>a.position-b.position||a.id-b.id);let html=title('PHOTO ALBUM','みんなの写真を、ここに。','写真をタップして大きく表示。左右のボタンやスワイプで続きを楽しめます。')+notice+'<div class="button-row"><a class="btn" href="#/my">写真を投稿する ↗</a>'+(aid?'<a class="btn btn-outline" href="#/gallery">アルバム一覧へ</a>':'')+(organizer()?'<a class="btn btn-outline" href="#/admin/photos">アルバムを管理</a>':'')+'</div>';if(state.settings.clock>state.settings.photoEnd)return frame(html+'<p class="panel">写真の公開期間は終了しました。</p>');if(!aid)html+='<div class="album-cover-grid">';for(const a of albums){if(aid&&a.id!==aid)continue;const photos=C.visiblePhotos(state,a.id);if(!aid){html+='<a class="album-cover" href="#/gallery/'+a.id+'">'+(photos.length?'<img src="'+esc(photos[0].src)+'" alt="'+esc(a.name)+'の表紙" loading="lazy">':'<div class="album-cover-empty">写真はこれから</div>')+'<div><h2>'+esc(a.name)+'</h2><span>'+photos.length+'枚</span><p>'+esc(a.description)+'</p></div></a>';continue;}html+='<section class="section"><div class="section-head"><div><h2>'+esc(a.name)+'</h2><p>'+esc(a.description)+'</p></div><strong>'+photos.length+'枚</strong></div><div class="photo-mosaic">'+photos.map(p=>'<article class="photo-tile"><a href="'+esc(p.src)+'" data-photo-view data-photo-group="'+a.id+'" data-title="'+esc(p.title)+'" data-caption="'+esc((p.caption||'')+(p.authorLabel?' ／ 投稿：'+p.authorLabel:''))+'" data-download="'+esc(p.src)+'" aria-label="'+esc(p.title)+'を大きく表示"><img src="'+esc(p.src)+'" alt="'+esc(p.title)+'" loading="lazy"></a><h3>'+esc(p.title)+'</h3>'+postCaption(p)+'<button class="link" data-action="download-photo" data-id="'+p.id+'">写真をダウンロード</button></article>').join('')+'</div>'+(!photos.length?'<p class="empty">写真は公開準備中です。</p>':'')+'</section>';}return frame(html+(!aid?'</div>':''));};
route();
